SWITCHVIEW_NEW = "function switchView(view) {\n  document.getElementById('view-waterfall').style.display = (view === 'logistica' || view === 'cobros') ? 'none' : 'block';\n  document.getElementById('view-logistica').style.display = view === 'logistica' ? 'block' : 'none';\n  document.getElementById('view-cobros').style.display    = view === 'cobros'    ? 'block' : 'none';\n  document.querySelectorAll('.tab-btn').forEach(b =>\n    b.classList.toggle('active', b.dataset.view === view || b.dataset.period === view));\n  if (view === 'logistica') renderLogistica();\n}"

# ── Helpers ───────────────────────────────────────────────────────────────────
def extract_json_value(html, start):
    brace_start = html.index("{", start)
    depth = 0; i = brace_start; in_str = False; esc = False
    while i < len(html):
        c = html[i]
        if esc: esc = False
        elif c == "\\" and in_str: esc = True
        elif c == "\"" and not esc: in_str = not in_str
        elif not in_str:
            if c == "{": depth += 1
            elif c == "}":
                depth -= 1
                if depth == 0: return html[brace_start:i+1], i+1
        i += 1
    raise ValueError("No matching brace")

def apply(html):
    changed = []

    # 1. CSS
    if "/* ── Cobros MLB vs HSP ── */" not in html:
        html = html.replace("  </style>", CSS_INJECT + "  </style>", 1)
        changed.append("CSS")

    # 2. Tab button
    if 'data-view="cobros"' not in html:
        old_btn = "onclick=\"switchView('logistica')\">Logística MLB vs HSP</button>"
        html = html.replace(old_btn, old_btn + "\n    " + TAB_BTN, 1)
        changed.append("tab-button")

    # 3. View div
    if 'id="view-cobros"' not in html:
        html = html.replace("</div><!-- /page -->", VIEW_HTML + "\n</div><!-- /page -->", 1)
        changed.append("view-div")

    # 4. switchView
    if "view === \'cobros\'" not in html and "view === \'cobros\'".replace("\'","'") not in html:
        for old_sv in [
            "function switchView(view) {\n  const isLog = view === \'logistica\';",
            "function switchView(view) {\n    // hide cobros view too",
        ]:
            old_sv_real = old_sv.replace("\'", "'")
            idx = html.find("function switchView(view)")
            if idx >= 0:
                end = html.find("\n}", idx) + 3
                html = html[:idx] + SWITCHVIEW_NEW + html[end:]
                changed.append("switchView")
                break

    # 5. switchPeriod: hide cobros
    sp_idx = html.find("function switchPeriod(key)")
    if sp_idx >= 0:
        sp_snippet = html[sp_idx:sp_idx+150]
        if "view-cobros" not in sp_snippet:
            html = html.replace(
                "function switchPeriod(key) {",
                "function switchPeriod(key) {\n  document.getElementById(\'view-cobros\').style.display = \'none\';",
                1
            )
            changed.append("switchPeriod")

    # 6. Drilldown data (both DRILLDOWN_ABR_MAI and DRILLDOWN_MAR_MAY)
    L2_JSON_KEY = json.dumps(L2_KEY)
    new_data = DRILLDOWN_DATA
    for var_name in ["DRILLDOWN_ABR_MAI", "DRILLDOWN_MAR_MAY"]:
        var_pos = html.find(f"const {var_name}")
        if var_pos < 0: continue
        SCAN = 180000
        offsets = [m.start() for m in re.finditer(re.escape(L2_JSON_KEY), html[var_pos:var_pos+SCAN])]
        sites = ["TOTAL","MLA","MLB","MLC","MLM"]
        adj = 0
        for idx_s, off in enumerate(offsets[:len(sites)]):
            site = sites[idx_s]
            abs_pos = var_pos + off + adj
            colon = html.index(":", abs_pos + len(L2_JSON_KEY))
            if colon > abs_pos + len(L2_JSON_KEY) + 5: continue
            old_val, end_pos = extract_json_value(html, colon)
            new_val = json.dumps(new_data[site], ensure_ascii=False, separators=(",",":"))
            json.loads(new_val)  # validate
            html = html[:colon+1] + new_val + html[end_pos:]
            adj += len(new_val) - len(old_val)
        changed.append(f"drilldown-{var_name}")

    return html, changed

# ── Main ──────────────────────────────────────────────────────────────────────
if __name__ == "__main__":
    with open(HTML_FILE, encoding="utf-8") as f:
        html = f.read()
    print(f"Input: {len(html):,} chars")

    html, changes = apply(html)
    print(f"Applied: {changes}")
    print(f"Output: {len(html):,} chars")

    # Sanity checks
    assert 'id="view-cobros"' in html, "ERROR: view-cobros missing"
    assert "view === \'cobros\'".replace("\'","'") in html, "ERROR: switchView not fixed"
    print("Checks: OK")

    with open(HTML_FILE, "w", encoding="utf-8") as f:
        f.write(html)
    print(f"Saved: {HTML_FILE}")
